{
  "root": "main",
  "state": {
    "itinerary": [
      {
        "dayDate": "Day 1",
        "area": "Central Kyoto",
        "morningActivity": "Arrival and hotel check-in",
        "afternoonActivity": "Nishi Hongan-ji or Higashi Hongan-ji",
        "dinnerSuggestion": "Kyoto-style set meal",
        "icon": "../assets/r_004421_01_1_geo-alt.svg"
      },
      {
        "dayDate": "Day 2",
        "area": "Arashiyama",
        "morningActivity": "Tenryu-ji and bamboo area",
        "afternoonActivity": "Okochi Sanso Garden or riverside cafe",
        "dinnerSuggestion": "Seasonal Kyoto dishes",
        "icon": "../assets/r_004421_01_2_tree.svg"
      },
      {
        "dayDate": "Day 3",
        "area": "Eastern Kyoto",
        "morningActivity": "Kiyomizu-dera",
        "afternoonActivity": "Kodai-ji or Yasaka Shrine",
        "dinnerSuggestion": "Gion/Higashiyama kaiseki",
        "icon": "../assets/r_004421_01_3_building.svg"
      },
      {
        "dayDate": "Day 4",
        "area": "Shopping/Departure",
        "morningActivity": "Kyoto Station/Shijo shopping",
        "afternoonActivity": "Kennin-ji or cafe rest",
        "dinnerSuggestion": "Casual final meal"
      }
    ],
    "budget": [
      { "category": "Hotel, 3 nights", "total": "$420" },
      { "category": "Food and drinks", "total": "$410" },
      { "category": "Local transit and taxis", "total": "$90" },
      { "category": "Temple admissions", "total": "$70" },
      { "category": "Shopping stop", "total": "$180" },
      { "category": "Buffer", "total": "$250" },
      { "category": "Trip total", "total": "$1,420" }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["title", "summary", "itineraryTable", "budgetTable", "actions"]
    },
    "title": { "type": "Text", "props": { "text": "Kyoto April 2026 Slow-Pace Trip", "variant": "h1" }, "children": [] },
    "summary": { "type": "Text", "props": { "text": "A 4-day Kyoto plan for two adults focusing on moderate walking, traditional food, and a $2,400 budget target." }, "children": [] },
    "itineraryTable": {
      "type": "Table",
      "props": {
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayDate",
        "statePath": "/itinerary",
        "columns": [
          { "key": "dayDate", "label": "Day" },
          { "key": "area", "label": "Area" },
          { "key": "morningActivity", "label": "Morning" },
          { "key": "afternoonActivity", "label": "Afternoon" },
          { "key": "dinnerSuggestion", "label": "Dinner" }
        ]
      },
      "children": []
    },
    "budgetTable": {
      "type": "Table",
      "props": {
        "domain": "generic",
        "preferredPresentation": "table",
        "statePath": "/budget",
        "columns": [
          { "key": "category", "label": "Category" },
          { "key": "total", "label": "Estimated Total" }
        ]
      },
      "children": []
    },
    "actions": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["btn1", "btn2", "btn3", "btn4"]
    },
    "btn1": { "type": "Button", "props": { "label": "Search Kyoto hotels", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.booking.com/city/jp/kyoto.en-gb.html" } } } }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Check train routes", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.hyperdia.com/" } } } }, "children": [] },
    "btn3": { "type": "Button", "props": { "label": "Kyoto tourism guide", "on": { "press": { "action": "openUrl", "params": { "url": "https://kyoto.travel/en" } } } }, "children": [] },
    "btn4": { "type": "Button", "props": { "label": "Temple hours and access", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.japan-guide.com/e/e2158.html" } } } }, "children": [] }
  }
}
